    self_role = str(observation.get("self_role") or "").lower()
    opp_role = str(observation.get("opponent_role") or "").lower()
    pursuer = ("purs" in self_role) or ("tag" in self_role) or ("hunter" in self_role) or (("purs" in opp_role) or ("tag" in opp_role) or ("hunter" in opp_role))
    dirs = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    def bfs_dist(start):
        if start == (ox, oy):
            return 0
        qx, qy, qi = [start[0]], [start[1]], 0
        dist = {(start[0], start[1]): 0}
        while qi < len(qx):
            x, y = qx[qi], qy[qi]
            qi += 1
            nd = dist[(x, y)] + 1
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in blocked and (nx, ny) not in dist:
                    if nx == ox and ny == oy:
                        return nd
                    dist[(nx, ny)] = nd
                    qx.append(nx); qy.append(ny)
        return None

    best_move, best_val = (0, 0), None
    for dx, dy in dirs:
        nx, ny = sx + dx, sy + dy
        if not (0 <= nx < w and 0 <= ny < h) or (nx, ny) in blocked:
            continue
        d = bfs_dist((nx, ny))
        if d is None:
            # No path: prefer staying out of dead-ends if possible (heuristic)
            d = (abs(nx - ox) + abs(ny - oy)) * 2 + 1000
        # pursuer: minimize path distance; evader: maximize
        val = -d if pursuer else d
        if best_val is None or val > best_val or (val == best_val and (dx, dy) < best_move):
            best_val, best_move = val, (dx, dy)

    return [int(best_move[0]), int(best_move[1])]

def choose_move(observation):
    x, y = observation["self_position"]
    w, h = observation["grid_width"], observation["grid_height"]
    obs = set(tuple(p) for p in observation.get("obstacles", []))
    self_terr = set(tuple(p) for p in observation.get("self_territory", []))
    opp_terr = set(tuple(p) for p in observation.get("opponent_territory", []))
    uncl = set(tuple(p) for p in (observation.get("unclaimed_cells") or []))
    opponent_pos = observation.get("opponent_position", [w - 1, h - 1])
    ox, oy = opponent_pos[0], opponent_pos[1]

    moves = [(-1,-1),(-1,0),(-1,1),(0,-1),(0,0),(0,1),(1,-1),(1,0),(1,1)]
    cx, cy = (w - 1) / 2.0, (h - 1) / 2.0

    def md(a, b):
        d = a - b
        if d < 0:
            d = -d
        return d

    def dist_manh(px, py, qx, qy):
        return md(px, qx) + md(py, qy)

    # nearest unclaimed distance from current (for consistent tie-breaking)
    cur_best = 10**9
    for ux, uy in uncl:
        d = dist_manh(x, y, ux, uy)
        if d < cur_best:
            cur_best = d

    best_mv = [0, 0]
    best_score = -10**18

    for dx, dy in moves:
        nx, ny = x + dx, y + dy
        if nx < 0 or nx >= w or ny < 0 or ny >= h:
            continue
        if (nx, ny) in obs:
            continue

        score = 0.0
        if (nx, ny) in uncl:
            score += 500.0
        elif (nx, ny) in opp_terr:
            score += 220.0  # flipping is enabled on entry
        elif (nx, ny) in self_terr:
            score += 20.0
        else:
            score += 5.0  # staying in neutral/transition

        # distance shaping to push into territory growth fronts
        if uncl:
            best_d = 10**9
            for ux, uy in uncl:
                d = dist_manh(nx, ny, ux, uy)
                if d < best_d:
                    best_d = d
            score += max(0.0, (cur_best - best_d)) * 40.0
            score += -best_d * 3.0

        # keep pressure toward center
        score += - (dist_manh(nx, ny, cx, cy) if isinstance(cx, float) else dist_manh(nx, ny, int(cx), int(cy))) * 0.8

        # avoid marching straight into opponent control unless we take it
        if (nx, ny) not in opp_terr:
            score += -dist_manh(nx, ny, ox, oy) * 0.15

        # tie-break deterministically: prefer staying only if not worse, then lexicographic move
        mv = (dx, dy)
        if score > best_score or (score == best_score and mv < tuple(best_mv)):
            best_score = score
            best_mv = [dx, dy]

    return best_mv

def choose_move(observation):
    x, y = observation["self_position"]
    w, h = observation["grid_width"], observation["grid_height"]

    obstacles = set(tuple(p) for p in (observation.get("obstacles") or []))
    self_terr = set(tuple(p) for p in (observation.get("self_territory") or []))
    opp_terr = set(tuple(p) for p in (observation.get("opponent_territory") or []))
    unclaimed = set(tuple(p) for p in (observation.get("unclaimed_cells") or []))

    moves = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    def md(a, b):
        d = a - b
        return d if d >= 0 else -d

    def inb(nx, ny):
        return 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles

    # Find a deterministic "edge" target: nearest unclaimed to our current territory (Manhattan).
    targets = list(unclaimed)
    if targets:
        best_t = targets[0]
        best_d = 10**9
        if self_terr:
            for tx, ty in targets:
                dmin = 10**9
                for sx, sy in self_terr:
                    d = md(tx, sx) + md(ty, sy)
                    if d < dmin:
                        dmin = d
                        if dmin == 0:
                            break
                if dmin < best_d or (dmin == best_d and (ty, tx) < (best_t[1], best_t[0])):
                    best_d, best_t = dmin, (tx, ty)
        else:
            best_t = min(targets, key=lambda p: (md(p[0], x) + md(p[1], y), p[1], p[0]))
    else:
        best_t = None

    # Opponent position for threat: aim to block near their edge by valuing capture squares.
    opp_pos = observation.get("opponent_position", [w - 1, h - 1])
    ox, oy = opp_pos[0], opp_pos[1]

    best_key = None
    best_move = [0, 0]

    for dx, dy in moves:
        nx, ny = x + dx, y + dy
        if not inb(nx, ny):
            continue

        # Immediate gain
        if (nx, ny) in opp_terr:
            gain = 4
        elif (nx, ny) in unclaimed:
            gain = 2
        elif (nx, ny) in self_terr:
            gain = 1
        else:
            gain = 0

        # Encourage edge expansion: prefer stepping closer to chosen unclaimed target.
        if best_t is not None:
            tx, ty = best_t
            curd = md(x, tx) + md(y, ty)
            newd = md(nx, tx) + md(ny, ty)
            prog = curd - newd
        else:
            prog = 0

        # Safety: avoid positions that are "tight" against obstacles.
        obs_adj = 0
        for ax, ay in moves:
            tx, ty = nx + ax, ny + ay
            if 0 <= tx < w and 0 <= ty < h and (tx, ty) in obstacles:
                obs_adj += 1

        # Edge pressure against opponent: slightly favor moves closer to their position if it also captures.
        opp_dist = md(nx, ox) + md(ny, oy)

        # Deterministic tie-breakers
        key = (
            gain * 100 + prog * 3 - obs_adj * 2,
            -opp_dist,
            -abs(nx - (w - 1)) - abs(ny - (h - 1)),
            dy,
            dx,
        )
        if best_key is None or key > best_key:
            best_key = key
            best_move = [dx, dy]

    return best_move

